  const cad = CAMPOS_CAD.map(([k, n]) => [n, pct(base.filter(s => k === 'impacto' ? num(s.impacto) > 0 : k === 'servidores' ? String(s.servidores ?? '') !== '' : String(s[k] || '').trim()).length, base.length)]);
