  const dv = (a, b, moeda) => { const x = b - a; return x ? `<span class="${x > 0 ? 'fin-pos' : 'fin-neg'}">${x > 0 ? '+' : '−'}${moeda ? fmtM(Math.abs(x)) : Math.abs(x).toLocaleString('pt-BR')}</span>` : '<span style="color:var(--mut2)">—</span>'; };
