  const csv = '﻿' + ['Código;Unidade escolar;DRE;Município;Tipo;Localidade;Alunos;Alunos da educação inclusiva;Profissionais;Endereço;Número;CEP;Bairro;Telefone;E-mail;Latitude;Longitude', ...l.map(e => [e.codigo, e.nome, e.dre, e.municipio, e.tipo, e.localidade, e.alunos, e.inclusiva || '', e.profissionais || '', e.endereco, e.numero, e.cep, e.bairro, e.telefone, e.email, String(e.latitude).replace('.', ','), String(e.longitude).replace('.', ',')].map(q).join(';'))].join('\r\n');
