  const av = C.map(c => { const M = metricasEstrutura(c.lista); return { c, M, r:avaliarCenario(c, M, base, mt) }; });
  const metas = av[0].r.map(x => x.k), sel = av.find(x => x.c.id === reSel) || av[0];
