function codigoValido(c){ const m = String(c || '').trim().toUpperCase().match(/^(GAB-[A-Z]{3}-\d{8}-[0-9A-Z]{4})([0-9A-Z])$/); return !!m && digitoCodigo(m[1]) === m[2]; }
