    const ring = Array.from({ length:33 }, (_, i) => { const a = i / 32 * 2 * Math.PI; return [+(n.lon + Math.cos(a) * n.raio / kx).toFixed(4), +(n.lat + Math.sin(a) * n.raio).toFixed(4)]; });
