  if (k === 'obrasdest') return apTelaObrasDest(D, A);
  if (k === 'convenios') return apTelaConvenios(D, A);
  if (k === 'noticias') return apTelaNoticias(A);
  if (k === 'dre') return apTelaDre(D, A);
  return apTelaFim(D, A);
