function apTurma(tipo){
  const br = (pts) => pts.map(([x, y, s], i) => `<path class="br" style="--i:${i}" transform="translate(${x} ${y}) scale(${s})" d="M0,-12Q2,-2 12,0Q2,2 0,12Q-2,2-12,0Q-2,-2 0,-12Z" fill="#fde68a"/>`).join('');
  if (tipo === 'fim') return `<svg class="apx-turma-svg" viewBox="0 0 790 360" role="img" aria-label="Alunos e professores dando tchau">${AP_PDEFS}${br([[30, 70, 1], [760, 60, .9], [400, 18, .8], [600, 30, .6], [200, 40, .7]])}
    ${apPessoa({ tipo:'profa', x:95, y:350, s:1.17, pele:'#e0ac69', cabelo:'#4a2c17', acena:1, oculos:true, d:-.3 })}
    ${apPessoa({ tipo:'menina', x:240, y:350, pele:'#8d5524', cabelo:'#1a1a1a', acena:2, boca:1, laco:'#facc15', mochila:'#ec4899', alca:'#be185d', d:-1.1 })}
    ${apPessoa({ tipo:'cadeira', x:392, y:350, pele:'#f1c27d', cabelo:'#6b3e1f', acena:1, boca:1, d:-.7 })}
    ${apPessoa({ tipo:'menino', x:545, y:350, pele:'#c68642', cabelo:'#2b1a10', acena:2, boca:1, mochila:'#22c55e', alca:'#15803d', d:-1.6 })}
    ${apPessoa({ tipo:'prof', x:695, y:350, s:1.2, pele:'#a16e4a', cabelo:'#374151', acena:1, oculos:true, camisa:'#0e7490', d:-.9 })}</svg>`;
  return `<svg class="apx-turma-svg" viewBox="0 0 560 310" role="img" aria-label="Estudantes da rede estadual">${AP_PDEFS}${br([[24, 60, 1], [536, 80, .8], [290, 14, .7], [520, 240, .6]])}
    ${apPessoa({ tipo:'menino', x:105, y:300, pele:'#c68642', cabelo:'#2b1a10', acena:1, d:0 })}
    ${apPessoa({ tipo:'cadeira', x:282, y:300, pele:'#f1c27d', cabelo:'#6b3e1f', d:-1.2 })}
    ${apPessoa({ tipo:'menina', x:452, y:300, s:.96, pele:'#8d5524', cabelo:'#1a1a1a', livro:'#dc2626', mochila:'#ec4899', alca:'#be185d', d:-1.8 })}</svg>`;
}
/* profissionais das escolas: campo por escola (vazio = sem informação) */
function apProf(A){ const c = A.es.filter(e => String(e.profissionais ?? '').trim() !== ''), n = c.reduce((t, e) => t + num(e.profissionais), 0), al = alunosDe(c); return { tem:c.length > 0, n, escolas:c.length, razao:n ? al / n : 0 }; }
/* educação inclusiva: campo por escola (alunos da educação inclusiva); sem ele, usa as escolas especializadas */
function apIncl(A){
  const comDado = A.es.filter(e => String(e.inclusiva ?? '').trim() !== ''), esp = A.es.filter(e => grupoTipo(e.tipo) === 'Especializada');
  return { tem:comDado.length > 0, n:comDado.reduce((t, e) => t + num(e.inclusiva), 0), escolas:comDado.filter(e => num(e.inclusiva) > 0).length, esp:esp.length, espAl:alunosDe(esp) };
}
const apEsOrd = A => [...A.es].filter(e => e.latitude && e.longitude).sort((a, b) => num(b.alunos) - num(a.alunos));
