    if (!ok) { r = await q('q=' + encodeURIComponent('Prefeitura Municipal de ' + A.nome + ', Mato Grosso')); ok = r.find(x => dentro(x) && ehPref(x)); }
    let v = ok ? { lat:+ok.lat, lon:+ok.lon, nome:'Prefeitura Municipal', aprox:false } : null;
    if (!v) { r = await q('city=' + encodeURIComponent(A.nome) + '&state=Mato%20Grosso'); const c = r.find(dentro); if (c) v = { lat:+c.lat, lon:+c.lon, nome:'Sede do município', aprox:true }; }
    try { if (v) localStorage.setItem(k, JSON.stringify({ t:Date.now(), v })); } catch (e) {}
