const OB_ABAS = [['painel', 'Painel', 'fa-gauge-high'], ['lista', 'Obras', 'fa-list'], ['mapa', 'Mapa', 'fa-map-location-dot'], ['inauguracoes', 'Inaugurações', 'fa-ribbon'], ['importar', 'Importar', 'fa-file-import']];
