function cvParams(){ const p = param('convParametros', null) || {}; const n = (k, d) => isFinite(+p[k]) && p[k] !== '' ? +p[k] : d;
  return { pf:n('pf', 35), pfin:n('pfin', 25), pp:n('pp', 20), pc:n('pc', 20), otima:n('otima', 85), boa:n('boa', 70), regular:n('regular', 50) }; }
