/* ---------- painel de Obras: tipos com ícones animados, rosca da situação, entregas por trimestre ---------- */
function obHero(L){
  const st = Object.keys(OB_ST).map(s => [s, L.filter(o => obStatus(o) === s).length, OB_ST[s]]).filter(f => f[1]);
  const tipos = {}; L.forEach(o => { const k = obObj(o); tipos[k] = tipos[k] || [0, 0]; tipos[k][0]++; tipos[k][1] += obValor(o); });
  const T = Object.entries(tipos).sort((a, b) => b[1][1] - a[1][1]).slice(0, 6), inv = L.reduce((t, o) => t + obValor(o), 0);
  const et = [['Em obra', 'Em obra', '#2563eb', 'fa-helmet-safety'], ['Concluída', 'Concluída', '#65a30d', 'fa-circle-check'], ['Pronta para inaugurar', 'Pronta', '#7c3aed', 'fa-flag-checkered'], ['Agendada', 'Agendada', '#0891b2', 'fa-calendar-check'], ['Inaugurada', 'Inaugurada', '#16a34a', 'fa-ribbon']].map(([k, t, c, ic]) => [k, t, c, ic, L.filter(o => obEtapa(o) === k).length]);
  const hoje = new Date(), q0 = hoje.getFullYear() * 4 + Math.floor(hoje.getMonth() / 3), B = [['Atrasadas', 0, '#dc2626']];
  for (let i = 0; i < 8; i++) { const q = q0 + i; B.push([`${q % 4 + 1}º tri/${String(Math.floor(q / 4)).slice(2)}`, 0, i < 1 ? '#f59e0b' : i < 3 ? '#0ea5e9' : '#6366f1']); }
  L.forEach(o => { if (obStatus(o) !== 'Em execução') return; const t = /^\d{4}-\d{2}/.test(o.previsao || '') ? Date.parse(o.previsao) : NaN; if (!isFinite(t)) return; const d = new Date(t), q = d.getFullYear() * 4 + Math.floor(d.getMonth() / 3); const i = t < Date.now() - 31 * 864e5 ? 0 : q - q0 + 1; if (i >= 0 && i <= 8) B[i][1]++; });
  const mx = Math.max(1, ...B.map(b => b[1]));
  return `<div class="cv-hero"><div class="cartao cv-h1"><h3><i class="fa-solid fa-shapes"></i>O que está sendo construído · <span data-cv-n>${fmtRc(inv)}</span></h3>
      <div class="cv-tipos ob-tipos">${T.map(([k, [n, v]], i) => `<button class="cv-tp" style="--i:${i}" onclick="${obIrLista({ objeto:k })}"><span class="ic">${OB_ANIM[k] || OB_ANIM.Outro}</span><b data-cv-n>${n}</b><small>${esc(k)}<br>${fmtRc(v)}</small></button>`).join('')}</div>
      <div class="ob-trilha">${et.map(([k, t, c, ic, n], i) => `<button style="--c:${c};--i:${i}" onclick="${obIrLista({ inaug:k === 'Em obra' ? 'Em obra' : k })}"><span><i class="fa-solid ${ic}"></i></span><b>${n}</b><small>${t}</small></button>`).join('')}</div></div>
    <div class="cartao cv-h2"><h3><i class="fa-solid fa-chart-pie"></i>Situação</h3>${cvRosca(st, String(L.length), 'obras', n => obIrLista({ status:n }))}</div>
    <div class="cartao cv-h3"><h3><i class="fa-solid fa-calendar-days"></i>Entregas previstas (obras em execução)</h3><div class="cv-vg">${B.map(([t, n, c], i) => `<div class="cv-vg-c" title="${esc(t)}: ${n} obra(s)" style="--c:${c};--h:${(n / mx * 100).toFixed(1)}%;--i:${i}"><b>${n || ''}</b><span><i></i></span><small>${t}</small></div>`).join('')}</div><p class="s">Por trimestre da previsão de conclusão; em vermelho, previsões já vencidas.</p></div></div>`;
}
/* pódio dos convênios: 3 melhores notas, cada um com sua miniatura 3D */
function cvPodio(M){
  const top = M.filter(m => m.nota !== null).sort((a, b) => b.nota - a.nota).slice(0, 3); if (top.length < 2) return '';
  const D = apDados(), ord = [top[1], top[0], top[2]].filter(Boolean), med = m => ['#f59e0b', '#94a3b8', '#b45309'][top.indexOf(m)];
  return `<div class="cartao cv-podio"><h3><i class="fa-solid fa-trophy"></i>Melhores desempenhos</h3><div class="cv-pod">${ord.map(m => { const g = D.muns.find(x => x.k === m.k), A = g ? { tipo:'mun', m:g, nome:g.nome, es:g.es, dre:g.dre, cor:CV_COR[m.cls] } : null, i = top.indexOf(m);
    return `<button class="cv-pod-i p${i + 1}" style="--c:${med(m)};--i:${i}" onclick="${cvIrLista({ mun:m.k })}">${A ? rl3D(D, A, { w:160, h:110, prof:7 }) : ''}<span class="md"><i class="fa-solid fa-medal"></i>${i + 1}º</span><b>${esc(m.nome)}</b><small>nota ${Math.round(m.nota)} · ${m.cls} · ${m.L.length} convênio${m.L.length === 1 ? '' : 's'}</small><span class="base"></span></button>`; }).join('')}</div></div>`;
}

/* Erros inesperados depois de aberto: avisa em vez de falhar em silêncio */
window.addEventListener('error', e => { if (window.GABORG_INICIADO && e.message && typeof toast === 'function') toast('Erro: ' + e.message + ' — recarregue a página. Se repetir, envie esta mensagem ao suporte.', 'erro'); });
window.addEventListener('unhandledrejection', e => { const m = e.reason && (e.reason.message || String(e.reason)); if (window.GABORG_INICIADO && m && !/abort/i.test(m) && typeof toast === 'function') console.warn('GABOrg:', m); });

/* ===================== AVISO DE ATUALIZAÇÃO DO APP ===================== */
/* Consulta o index.html publicado (sem cache). Se a versão lá for mais nova que a que está rodando, avisa e oferece atualizar. */
const atu = { nova:'', dispensadaEm:0, ultima:0 };
function compararVersao(a, b){ const x = String(a).split('.').map(Number), y = String(b).split('.').map(Number); for (let i = 0; i < Math.max(x.length, y.length); i++) { const d = (x[i] || 0) - (y[i] || 0); if (d) return d > 0 ? 1 : -1; } return 0; }
async function verificarAtualizacao(manual){
  if (!/^https?:$/.test(location.protocol)) { if (manual) toast('A verificação só funciona com o sistema publicado (GitHub Pages).', 'aviso'); return; }
  atu.ultima = Date.now();
  try {
    const r = await fetch(location.pathname.replace(/[^/]*$/, '') + 'index.html?nc=' + Date.now(), { cache:'no-store' });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const h = await r.text(), m = h.match(/GABORG_VERSAO_HTML\s*=\s*'([\d.]+)'/) || h.match(/arquivo\.js\?v=([\d.]+)/), n = h.match(/GABORG_NOVIDADES\s*=\s*"([^"]*)"/);
    const nova = m && m[1];
    if (nova && compararVersao(nova, VERSAO) > 0) { atu.nova = nova; mostrarAtualizacao(nova, n ? n[1] : '', manual); }
    else if (manual) toast(`Você já está na versão mais recente (${VERSAO}).`);
  } catch (e) { if (manual) toast('Não foi possível verificar agora: ' + e.message, 'aviso'); }
}
/* novidades: só as versões entre a atual e a nova, uma por item, curtas */
function novidadesAtu(txt, nova){
  const L = String(txt || '').replace(/\\n/g, '\n').split(/\n+/).map(x => x.trim()).filter(Boolean), it = [];
  L.forEach(x => { const m = x.match(/^(\d+\.\d+\.\d+)\s*[—–-]\s*(.+)$/); if (m) { if (compararVersao(m[1], VERSAO) > 0 && compararVersao(m[1], nova) <= 0) it.push([m[1], m[2]]); } });
  return it;
}
function mostrarAtualizacao(nova, novidades, manual){
  if (!manual && atu.dispensadaEm && Date.now() - atu.dispensadaEm < 30 * 60 * 1000) return;
  let el = $('#atu-app');
  if (!el) { el = document.createElement('div'); el.id = 'atu-app'; el.className = 'atu-app'; el.setAttribute('role', 'alert'); document.body.appendChild(el); }
  const pend = (typeof fila !== 'undefined' && fila.length) ? fila.length : 0, N = novidadesAtu(novidades, nova);
  el.innerHTML = `<div class="atu-in">
    <div class="atu-top"><span class="atu-ic"><i class="fa-solid fa-rocket"></i><i class="fa-solid fa-star s1"></i><i class="fa-solid fa-star s2"></i></span>
      <div class="atu-t"><b>Nova versão no ar</b><span class="atu-v"><em>${esc(VERSAO)}</em><i class="fa-solid fa-arrow-right-long"></i><em class="n">${esc(nova)}</em></span></div>
      <button class="atu-x" onclick="dispensarAtualizacao()" title="Depois" aria-label="Fechar"><i class="fa-solid fa-xmark"></i></button></div>
    ${N.length ? `<details class="atu-nov"><summary><i class="fa-solid fa-wand-magic-sparkles"></i>O que há de novo <small>${N.length}</small><i class="fa-solid fa-chevron-down sv"></i></summary><ul>${N.slice(0, 6).map(([v, t]) => `<li><em>${esc(v)}</em><span>${esc(t.length > 150 ? t.slice(0, 147).replace(/\s+\S*$/, '') + '…' : t)}</span></li>`).join('')}${N.length > 6 ? `<li class="mais">e mais ${N.length - 6} versões</li>` : ''}</ul></details>` : ''}
    ${pend ? `<p class="atu-pd"><i class="fa-solid fa-cloud-arrow-up"></i>${pend} alteração(ões) não enviada(s) ficam guardadas.</p>` : ''}
    <div class="atu-bt"><button class="atu-go" onclick="atualizarApp()"><span class="atu-bar"></span><i class="fa-solid fa-bolt"></i><span class="tx">Atualizar agora</span></button><button class="atu-dp" onclick="dispensarAtualizacao()">Depois</button></div></div>`;
  requestAnimationFrame(() => el.classList.add('on'));
}
function dispensarAtualizacao(){ atu.dispensadaEm = Date.now(); const el = $('#atu-app'); if (el) { el.classList.remove('on'); setTimeout(() => el.remove(), 350); } }
function atualizarApp(){
  const el = $('#atu-app'), b = el && el.querySelector('.atu-go');
  if (b) { b.classList.add('vai'); b.disabled = true; b.querySelector('.tx').textContent = 'Atualizando…'; const d = el.querySelector('.atu-dp'); if (d) d.hidden = true; }
  try { if (typeof salvarLocal === 'function') salvarLocal(); } catch (e) {}
  setTimeout(() => window.GABORG_LIMPAR(), b ? 900 : 0);
}
setTimeout(() => verificarAtualizacao(false), 8000);
setInterval(() => { if (!document.hidden) verificarAtualizacao(false); }, 15 * 60 * 1000);
document.addEventListener('visibilitychange', () => { if (!document.hidden && Date.now() - atu.ultima > 5 * 60 * 1000) verificarAtualizacao(false); });

/* ===================== MENU DO USUÁRIO ===================== */
function menuUsuario(){
  const sync = $('#sync') ? $('#sync').outerHTML : '';
  const m = document.createElement('div'); m.className = 'modal';
  const escuro = document.documentElement.dataset.tema === 'escuro';
  m.innerHTML = `<div class="cx" role="dialog" aria-modal="true" style="max-width:380px"><div class="menu-u">
    <div class="cab"><span class="av">${esc(iniciais(cfg.usuario || cfg.login))}</span><div style="min-width:0"><b>${esc(cfg.usuario || cfg.login || 'Usuário')}</b><small>${esc(cfg.login || '')} · ${esc(cfg.perfil || '')}</small>${sync}</div></div>
    ${appInstalavel() ? '<button class="it" data-a="instalar"><i class="fa-solid fa-download"></i>Instalar o GABOrg como app</button>' : ''}
    <button class="it" data-a="atualizar"><i class="fa-solid fa-rotate"></i>${atu.nova ? `Atualizar para a versão ${esc(atu.nova)}` : 'Verificar atualização'}<small style="margin-left:auto;color:var(--mut2)">v${VERSAO}</small></button>
    <button class="it" data-a="busca"><i class="fa-solid fa-magnifying-glass"></i>Busca rápida</button>
    <button class="it" data-a="ap"><i class="fa-solid fa-person-chalkboard"></i>Apresentação</button>
    <button class="it" data-a="tema"><i class="fa-solid fa-circle-half-stroke"></i>${escuro ? 'Tema claro' : 'Tema escuro'}</button>
    <button class="it" data-a="senha"><i class="fa-solid fa-key"></i>Alterar minha senha</button>
    <button class="it" data-a="config"><i class="fa-solid fa-gear"></i>Configurações</button>
    <button class="it perigo" data-a="sair"><i class="fa-solid fa-power-off"></i>Sair</button>
    <button class="it" data-a="fechar" style="justify-content:center;color:var(--mut)">Fechar</button>
  </div></div>`;
  m.addEventListener('click', e => {
    const b = e.target.closest('[data-a]'); if (!b && e.target !== m) return;
    m.remove(); const a = b && b.dataset.a;
    if (a === 'instalar') instalarApp();
    if (a === 'atualizar') { if (atu.nova) atualizarApp(); else verificarAtualizacao(true); }
    if (a === 'busca') setTimeout(abrirPaleta, 50);
    if (a === 'ap') trocarVista('apresentacao');
    if (a === 'tema') alternarTema();
    if (a === 'senha') modalTrocarSenha(false);
    if (a === 'config') trocarVista('config');
    if (a === 'sair') sair();
  });
  document.body.appendChild(m);
}

/* ===================== CELULAR: MENU "MAIS" (todas as seções numa folha que sobe de baixo) ===================== */
const NAV_FIXOS = ['mapa', 'escolas', 'convenios', 'apresentacao'];
function abrirMaisMenu(){
  fecharMaisMenu(); const nav = $('.lado nav'); if (!nav) return;
  const grupos = []; let g = null;
  [...nav.children].forEach(el => { if (el.tagName === 'H6') { g = { t:el.textContent, it:[] }; grupos.push(g); } else if (g && el.classList.contains('nav-b') && el.dataset.vista && !el.classList.contains('nav-mais') && !el.classList.contains('hidden') && (typeof podeVerVista !== 'function' || podeVerVista(el.dataset.vista)) && !(el.classList.contains('so-adm') && !ehAdmin())) g.it.push(el); });
  const f = document.createElement('div'); f.className = 'mais-f'; f.id = 'mais-f';
  f.innerHTML = `<div class="mais-fundo" onclick="fecharMaisMenu()"></div><div class="mais-cx" role="dialog" aria-label="Todas as seções"><span class="mais-alca"></span>
    <div class="mais-topo"><button class="mais-busca" onclick="fecharMaisMenu();abrirPaleta()"><i class="fa-solid fa-magnifying-glass"></i>Buscar setor, escola, município...</button>
      ${appInstalavel() ? '<button class="mais-inst" onclick="fecharMaisMenu();instalarApp()"><i class="fa-solid fa-download"></i>Instalar</button>' : ''}</div>
    ${grupos.filter(x => x.it.length).map(x => `<h6>${esc(x.t)}</h6><div class="mais-g">${x.it.map(b => `<button class="${b.dataset.vista === vistaAtual ? 'on' : ''}" onclick="fecharMaisMenu();trocarVista('${b.dataset.vista}')">${b.querySelector('i').outerHTML}<span>${esc(b.querySelector('span').textContent)}</span>${b.querySelector('.qt:not(.hidden)') ? `<em>${esc(b.querySelector('.qt').textContent)}</em>` : ''}</button>`).join('')}</div>`).join('')}
    <div class="mais-pe"><button onclick="fecharMaisMenu();menuUsuario()"><i class="fa-solid fa-circle-user"></i>Minha conta</button><button onclick="alternarTema()"><i class="fa-solid fa-circle-half-stroke"></i>Tema</button><button onclick="fecharMaisMenu();sair()"><i class="fa-solid fa-power-off"></i>Sair</button></div></div>`;
  document.body.appendChild(f); requestAnimationFrame(() => f.classList.add('on'));
  const cx = f.querySelector('.mais-cx'); let y0 = null;
  cx.addEventListener('touchstart', e => { if (cx.scrollTop <= 0) y0 = e.touches[0].clientY; }, { passive:true });
  cx.addEventListener('touchmove', e => { if (y0 === null) return; const d = e.touches[0].clientY - y0; if (d > 0) cx.style.transform = `translateY(${d}px)`; }, { passive:true });
  cx.addEventListener('touchend', e => { if (y0 === null) return; const d = (e.changedTouches[0].clientY - y0); y0 = null; cx.style.transform = ''; if (d > 90) fecharMaisMenu(); });
}
function fecharMaisMenu(){ const f = $('#mais-f'); if (!f) return; f.classList.remove('on'); setTimeout(() => f.remove(), 250); }
window.addEventListener('popstate', fecharMaisMenu);

/* ===================== DOBRÁVEIS (Galaxy Z Fold e similares) =====================
 * Quando o aparelho informa duas áreas de tela (dobra em pé ou deitada), cada seção com lista e detalhe
 * põe um lado em cada metade, sem nada em cima da dobra. */
function telasDobravel(){
  const r = document.documentElement; let s = null;
  try { s = (window.viewport && window.viewport.segments) || (window.getWindowSegments && window.getWindowSegments()) || null; } catch (e) {}
  let modo = '';
  if (s && s.length === 2) {
    const [a, b] = s, ax = a.x ?? a.left, ay = a.y ?? a.top, bx = b.x ?? b.left, by = b.y ?? b.top;
    if (Math.abs(ay - by) < 2) { modo = 'h'; r.style.setProperty('--seg-a', a.width + 'px'); r.style.setProperty('--dobra', Math.max(0, bx - (ax + a.width)) + 'px'); }
    else { modo = 'v'; r.style.setProperty('--seg-a', a.height + 'px'); r.style.setProperty('--dobra', Math.max(0, by - (ay + a.height)) + 'px'); }
  }
  r.classList.toggle('telas-h', modo === 'h'); r.classList.toggle('telas-v', modo === 'v');
  r.classList.toggle('dobravel-aberto', !modo && window.innerWidth > 640 && window.innerWidth / window.innerHeight > .8 && window.innerWidth / window.innerHeight < 1.35 && matchMedia('(pointer:coarse)').matches);
  if (modo && typeof mt !== 'undefined' && mt.mapa) setTimeout(() => mt.mapa.invalidateSize(), 200);
}
window.addEventListener('resize', () => { clearTimeout(telasDobravel.t); telasDobravel.t = setTimeout(telasDobravel, 100); });
if (window.viewport && window.viewport.addEventListener) try { window.viewport.addEventListener('segmentschange', telasDobravel); } catch (e) {}
telasDobravel();

/* ===================== APP INSTALÁVEL (PWA) ===================== */
let pedidoInstalacao = null;
const ehIOS = () => /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
const rodandoComoApp = () => window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
const appInstalavel = () => !rodandoComoApp() && (!!pedidoInstalacao || (ehIOS() && location.protocol === 'https:'));
function atualizarInstalavel(){ document.body.classList.toggle('pode-instalar', appInstalavel()); }
window.addEventListener('beforeinstallprompt', e => { e.preventDefault(); pedidoInstalacao = e; atualizarInstalavel(); });
window.addEventListener('appinstalled', () => { pedidoInstalacao = null; atualizarInstalavel(); toast('GABOrg instalado. Abra pelo ícone na tela inicial.'); });
async function instalarApp(){
  if (pedidoInstalacao) {
    pedidoInstalacao.prompt();
    try { await pedidoInstalacao.userChoice; } catch (e) {}
    pedidoInstalacao = null; atualizarInstalavel(); return;
  }
  if (ehIOS()) return abrirModal({ titulo:'Instalar no iPhone ou iPad', rotulo:'Entendi', semCancelar:true,
    html:`<p>No <b>Safari</b>:</p><ol style="margin:0;padding-left:20px;font-size:13.5px;line-height:1.9;color:var(--txt2)"><li>Toque em <b>Compartilhar</b> <i class="fa-solid fa-arrow-up-from-bracket"></i> na barra do navegador.</li><li>Escolha <b>Adicionar à Tela de Início</b>.</li><li>Confirme em <b>Adicionar</b>. O GABOrg abre em tela cheia, como um app.</li></ol>` });
  toast('Use o menu do navegador › "Instalar app" ou "Adicionar à tela inicial".');
}
// Service worker (sw.js): abre sem internet com os últimos dados guardados; página e arquivo.js vêm sempre da rede quando há conexão.
if ('serviceWorker' in navigator && location.protocol === 'https:') window.addEventListener('load', () => navigator.serviceWorker.register('sw.js').catch(() => {}));
atualizarInstalavel();

window.GABORG_VERSAO_JS = VERSAO;
(async function iniciar(){
  window.GABORG_INICIADO = true;
  if (window.GABORG_VERSAO_HTML && window.GABORG_VERSAO_HTML !== VERSAO) setTimeout(() => toast(`Versões diferentes: index.html ${window.GABORG_VERSAO_HTML} × arquivo.js ${VERSAO}. Envie os dois arquivos da mesma versão ao GitHub.`, 'aviso'), 1500);
  $('#lg-login').value = cfg.login || ''; $('#lg-url').value = cfg.url || URL_PADRAO;
  $('#lg-lembrar').checked = sessao.lembrado();
  if (!cfg.token || !cfg.url || cfg.modo !== 'nuvem') return mostrarLogin();
  const d = store.get('gaborg_db', null);
  if (d && Array.isArray(d.setores) && d.setores.length) { DB = d; TABS_DB.forEach(t => DB[t] = (DB[t] || []).map(x => novoReg(t, x))); abrirApp(); }
  try {
    const me = await chamar({ action:'me' }, 30000);
    if (me.status !== 'success') { if (me.code !== 'AUTH') throw new Error(me.message); return; }
    aplicarUsuario(me.usuario);
    if (me.usuario.trocarSenha === 'Sim') { const ok = await modalTrocarSenha(true); if (!ok) return; }
    await carregarNuvem();
    if (!$('#app').classList.contains('hidden')) redesenharTudo(); else abrirApp();
    statusSync();
  } catch (e) {
    ultimoErro = e.message; statusSync();
    if ($('#app').classList.contains('hidden')) mostrarLogin(e.message);
  }
})();
